import { BottomSheet, type BottomSheetCloseDetail } from '@absoluteui/components/bottom-sheet';

const targets = document.createElement('ul');
const sheet = BottomSheet.create({ title: 'Share', description: 'Choose where to send the link.', content: targets });
sheet.element.addEventListener('aui-close', (event) => {
  const { reason } = (event as CustomEvent<BottomSheetCloseDetail>).detail;
  if (reason === 'drag') {
    // the user dragged the sheet away
  }
});
document.querySelector('#share')?.addEventListener('click', () => {
  sheet.open();
});

import { BottomSheet, type BottomSheetSnapChangeDetail } from '@absoluteui/components/bottom-sheet';

const results = BottomSheet.create({
  title: 'Nearby places',
  modal: false,
  snapPoints: [0.25, 0.5, 0.9],
  snap: 1,
  closeOnDragDown: false,
});
results.element.addEventListener('aui-snap-change', (event) => {
  const { value } = (event as CustomEvent<BottomSheetSnapChangeDetail>).detail;
  results.body.classList.toggle('is-expanded', value >= 0.9);
});
results.open();
results.snapTo(2);

import { BottomSheet, type BottomSheetCloseDetail } from '@absoluteui/components/bottom-sheet';

let dirty = false;
const form = document.createElement('form');
form.addEventListener('input', () => {
  dirty = true;
});
const sheet = BottomSheet.create({ title: 'Add note', content: form, closeOnBackdrop: false });
sheet.element.addEventListener('aui-cancel', (event) => {
  const { reason } = (event as CustomEvent<BottomSheetCloseDetail>).detail;
  // Accidental dismissals (Escape, drag) are blocked; the close button still closes.
  if (dirty && reason !== 'close-button') event.preventDefault();
});
sheet.open();
